122	## Next 16: src/proxy.ts (file `src/proxy.ts`, export `proxy` — `middleware` is deprecated)
123	```ts
124	import { createServerClient } from "@supabase/ssr";
125	import { NextResponse, type NextRequest } from "next/server";
126	
127	export async function proxy(request: NextRequest) {
128	  let response = NextResponse.next({ request });
129	  const supabase = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
130	    cookies: {
131	      getAll() { return request.cookies.getAll(); },
132	      setAll(cookiesToSet, headers) {
133	        cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
134	        response = NextResponse.next({ request });
135	        cookiesToSet.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
136	        Object.entries(headers ?? {}).forEach(([k, v]) => response.headers.set(k, v)); // no-cache headers
137	      },
138	    },
139	  });
140	  await supabase.auth.getUser(); // refresh only; NO redirect -> API routes return their own 401
141	  return response;
142	}
143	export const config = {
144	  matcher: ["/((?!api/webhooks|_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)"],
145	};
146	```
147	
148	## src/lib/supabase/server.ts
149	```ts
150	import { createServerClient } from "@supabase/ssr";
151	import { cookies } from "next/headers";
152	export async function createClient() {
153	  const cookieStore = await cookies();
154	  return createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
155	    cookies: {
156	      getAll() { return cookieStore.getAll(); },
157	      setAll(cookiesToSet) {
158	        try { cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options)); }
159	        catch { /* Server Component: proxy refreshes */ }
160	      },
161	    },
162	  });
163	}
164	```
165	src/app/api/me/route.ts: `const { data: { user } } = await (await createClient()).auth.getUser(); if (!user) return NextResponse.json({ error: "unauthenticated" }, { status: 401 });`
166	Verified: curl /api/me → 401 (not 307); with cookie `sb-127-auth-token=base64-<base64url(JSON session)>` → 200.
167	
168	## vitest.config.mts + tests/global-setup.ts
169	```ts
170	// vitest.config.mts
171	import { defineConfig } from "vitest/config";
172	import nextEnv from "@next/env";
173	nextEnv.loadEnvConfig(process.cwd());
174	export default defineConfig({ resolve: { tsconfigPaths: true }, test: {
175	  environment: "node", include: ["tests/**/*.test.ts"], globalSetup: ["tests/global-setup.ts"],
176	  testTimeout: 30_000, hookTimeout: 180_000 } });
177	```
178	```ts
179	// tests/global-setup.ts
180	import { spawn, type ChildProcess } from "node:child_process";
181	const PORT = 3100, BASE = `http://localhost:${PORT}`;
182	let child: ChildProcess | undefined;
183	const up = () => fetch(`${BASE}/api/me`, { signal: AbortSignal.timeout(2000) }).then(() => true, () => false);
184	export async function setup() {
185	  process.env.TEST_BASE_URL = BASE;            // visible in test workers
186	  if (await up()) return;
187	  child = spawn("npx", ["next", "dev", "-p", String(PORT)], { stdio: "ignore", detached: true, env: { ...process.env } });
188	  for (const end = Date.now() + 120_000; Date.now() < end; await new Promise((r) => setTimeout(r, 1000)))
189	    if (await up()) return;
190	  throw new Error(`next dev did not come up on ${PORT}`);
191	}
192	export async function teardown() { if (child?.pid) try { process.kill(-child.pid, "SIGTERM"); } catch {} } // kill process group
193	```
194	Test sign-in: `createClient(url, anon, { auth: { persistSession: false } })` → `signInWithPassword` → `from("memberships").select()` returns 1 row; passed under TZ=UTC, Asia/Dubai, America/New_York.
195	
196	Verified: signInWithPassword works for each seeded user (manager@demo.test, tenant@demo.test / password123) after `supabase db reset`; each sees only own membership; both see the org via has_role.
